from collections import deque

def adjacency(n, edges, directed=False):
    if type(n) is not int or n < 0:
        raise ValueError("invalid vertex count")
    rows = [[] for _ in range(n)]
    for u, v in edges:
        if type(u) is not int or type(v) is not int or not 0 <= u < n or not 0 <= v < n:
            raise ValueError("invalid endpoint")
        rows[u].append(v)
        if not directed:
            rows[v].append(u)
    return rows

def breadth_first(rows, source):
    if type(source) is not int or not 0 <= source < len(rows):
        raise ValueError("invalid source")
    distance = [None] * len(rows)
    parent = [None] * len(rows)
    distance[source] = 0
    pending = deque([source])
    while pending:
        vertex = pending.popleft()
        for neighbor in rows[vertex]:
            if distance[neighbor] is None:
                distance[neighbor] = distance[vertex] + 1
                parent[neighbor] = vertex
                pending.append(neighbor)
    return distance, parent

