def connected_components(rows):
    # Precondition: validated adjacency of an undirected graph.
    component = [None] * len(rows)
    next_id = 0
    for start in range(len(rows)):
        if component[start] is not None:
            continue
        component[start] = next_id
        pending = [start]
        while pending:
            vertex = pending.pop()
            for neighbor in rows[vertex]:
                if component[neighbor] is None:
                    component[neighbor] = next_id
                    pending.append(neighbor)
        next_id += 1
    return component

