def lca_queries(n, parents, queries):
    children = [[] for _ in range(n + 1)]
    immediate = [1] * (n + 1)
    for (child, parent) in enumerate(parents, 2):
        immediate[child] = parent
        children[parent].append(child)
    depth = [0] * (n + 1)
    pending = [1]
    while pending:
        node = pending.pop()
        for child in children[node]:
            depth[child] = depth[node] + 1
            pending.append(child)
    levels = max(1, n.bit_length())
    up = [immediate]
    for _ in range(1, levels):
        prev = up[-1]
        up.append([prev[prev[v]] for v in range(n + 1)])
    out = []
    for (u, v) in queries:
        if depth[u] < depth[v]:
            (u, v) = (v, u)
        difference = depth[u] - depth[v]
        for k in range(levels):
            if difference >> k & 1:
                u = up[k][u]
        if u != v:
            for k in range(levels - 1, -1, -1):
                if up[k][u] != up[k][v]:
                    (u, v) = (up[k][u], up[k][v])
            u = up[0][u]
        out.append(str(u))
    return out

print(lca_queries(7, [1, 1, 2, 2, 3, 3], [(4, 5), (4, 6), (5, 5), (7, 1)]))
print(lca_queries(3, [3, 1], [(2, 3), (2, 1)]))

