def is_bst(nodes):
    stack = [(0, None, None)]
    while stack:
        (at, lower, upper) = stack.pop()
        (value, left, right) = nodes[at]
        if lower is not None and value <= lower:
            return ['INVALID']
        if upper is not None and value >= upper:
            return ['INVALID']
        if right != -1:
            stack.append((right, value, upper))
        if left != -1:
            stack.append((left, lower, value))
    return ['VALID']

print(*is_bst([(10, 1, -1), (5, -1, 2), (12, -1, -1)]))
